function formatPostTime(postTime: Date): string {
  const now = new Date();
  const elapsedMilliseconds = now.getTime() - postTime.getTime();
  const elapsedSeconds = Math.floor(elapsedMilliseconds / 1000);
  const elapsedMinutes = Math.floor(elapsedSeconds / 60);
  const elapsedHours = Math.floor(elapsedMinutes / 60);
  const elapsedDays = Math.floor(elapsedHours / 24);

  if (elapsedDays >= 365) {
    return `${Math.floor(elapsedDays / 365)} year${elapsedDays / 365 > 1 ? 's' : ''} ago`;
  } else if (elapsedDays >= 7) {
    return `${Math.floor(elapsedDays)} day${elapsedDays > 1 ? 's' : ''} ago`;
  } else if (elapsedHours >= 1) {
    return `${Math.floor(elapsedHours)} hour${elapsedHours > 1 ? 's' : ''} ago`;
  } else if (elapsedMinutes >= 1) {
    return `${Math.floor(elapsedMinutes)} minute${elapsedMinutes > 1 ? 's' : ''} ago`;
  } else if (elapsedSeconds >= 1) {
    return `${Math.floor(elapsedSeconds)} second${elapsedSeconds > 1 ? 's' : ''} ago`;
  } else {
    return 'just now';
  }
}

