/**
 * Compares two Excel files and returns an array of discrepancies.
 *
 * @param {string} file1Path - The path to the first Excel file.
 * @param {string} file2Path - The path to the second Excel file.
 * @returns {Array<Object>} An array of discrepancy objects. Each object has the following properties:
 *   - row: The row number where the discrepancy was found (1-based).
 *   - column: The column number where the discrepancy was found (1-based).
 *   - file1Value: The value in the first file.
 *   - file2Value: The value in the second file.
 */
async function compareExcelFiles(file1Path, file2Path) {
  try {
    const workbook1 = XLSX.readFile(file1Path);
    const workbook2 = XLSX.readFile(file2Path);

    const sheetName1 = workbook1.SheetNames[0];
    const sheetName2 = workbook2.SheetNames[0];

    const sheet1 = workbook1.Sheets[sheetName1];
    const sheet2 = workbook2.Sheets[sheetName2];

    const data1 = XLSX.utils.sheet_to_json(sheet1);
    const data2 = XLSX.utils.sheet_to_json(sheet2);

    const discrepancies = [];

    if (data1.length !== data2.length) {
      console.warn("Files have different number of rows.  Comparison may be inaccurate.");
    }

    for (let i = 0; i < data1.length; i++) {
      const row1 = data1[i];
      const row2 = data2[i];

      for (const column in row1) {
        if (row1.hasOwnProperty(column)) {
          const value1 = row1[column];
          const value2 = row2[column];

          if (value1 !== value2) {
            discrepancies.push({
              row: i + 1,
              column: column,
              file1Value: value1,
              file2Value: value2,
            });
          }
        }
      }
    }

    return discrepancies;
  } catch (error) {
    console.error("Error comparing Excel files:", error);
    return [];
  }
}

